using Mailjet.Client;using Mailjet.Client.Resources;using Newtonsoft.Json.Linq;using Notification.Api.Interfaces;using Notification.Api.Models;namespace Notification.Api.Infrastructure;public sealed class SendEmailMailjet(    IMailjetClient mailjetClient,    ILogger<SendEmailMailjet> logger) : IEmailSender{    public const string EmailTitle = "Title";    public async Task<SendEmailResponseModel> SendEmailAsync(        SendEmailModel model,        CancellationToken cancellationToken = default)    {
        ArgumentException.ThrowIfNullOrEmpty(model.To);        var mailjetRequest = BuildRequest(model);        try        {            logger.LogInformation("Start sending email message");            var response = await mailjetClient.PostAsync(mailjetRequest);            if (response.IsSuccessStatusCode)            {                return new SendEmailResponseModel(response.IsSuccessStatusCode);            }            var errorMessage = response.GetErrorMessage();            return new SendEmailResponseModel(response.IsSuccessStatusCode, errorMessage);        }        catch (Exception ex)        {            logger.LogError(ex.Message, ex);            throw;        }    }    private MailjetRequest BuildRequest(SendEmailModel model)
    {
        var mailjetRequst = new MailjetRequest        {            Resource = Contact.Resource        };        mailjetRequst.Property(Contact.Email, model.To);        mailjetRequst.Property(EmailTitle, string.Empty);        mailjetRequst.Property(Contact.IsExcludedFromCampaigns, false);        mailjetRequst.Property(Contact.Status, "Policy created");        mailjetRequst.Body = JObject.Parse(model.Body);

        return mailjetRequst;
    }}